    code: "// ===== Run field: heart-rate zone, timer, distance, average / lap / last-lap pace, optional route trail =====\n\n    function fldInit() as Void {\n        _fZones = [95, 114, 133, 152, 171, 190];\n        var z = UserProfile.getHeartRateZones(UserProfile.HR_ZONE_SPORT_RUNNING);\n        if (z != null && z.size() >= 6) { _fZones = z; }\n        if (FLD_MAP) {\n            _fLat = new [160];\n            _fLon = new [160];\n        }\n    }\n\n    function fldReset() as Void {\n        _fTimer = 0;\n        _fDist = 0.0;\n        _fPrevTimer = 0;\n        _fPrevDist = 0.0;\n        _fLapT0 = 0;\n        _fLapD0 = 0.0;\n        _fLapNo = 1;\n        _fLastLap = -1.0;\n        _fVirtT = -100000;\n        _fN = 0;\n        _fStep = 15.0;\n        _fHave = false;\n    }\n\n    // called every second with the activity data\n    function fldCompute(info as Activity.Info) as Void {\n        _fHr = info.currentHeartRate;\n        var t = (info.timerTime != null) ? info.timerTime : 0;\n        var d = (info.elapsedDistance != null) ? info.elapsedDistance : 0.0;\n        if (FLD_AUTO && d >= _fLapD0 + FLD_LAP_M && d > _fPrevDist) {\n            // crossed a lap mark since the previous second: interpolate the exact crossing time\n            var mark = _fLapD0 + FLD_LAP_M;\n            var f = (mark - _fPrevDist) / (d - _fPrevDist);\n            var tc = _fPrevTimer + (f * (t - _fPrevTimer)).toNumber();\n            fldEndLap(tc, mark);\n            _fVirtT = t;\n        }\n        _fTimer = t;\n        _fDist = d;\n        _fPrevTimer = t;\n        _fPrevDist = d;\n        if (FLD_MAP) { fldTrack(info); }\n    }\n\n    // Lap button (or the watch's own Auto Lap)\n    function fldLap() as Void {\n        if (_fTimer - _fVirtT < 3000) { return; }   // the watch lapped right after our own auto lap: ignore the duplicate\n        fldEndLap(_fTimer, _fDist);\n    }\n\n    function fldEndLap(tEnd as Number, dEnd as Float) as Void {\n        var dist = dEnd - _fLapD0;\n        if (dist >= 20.0) {\n            _fLastLap = ((tEnd - _fLapT0) / 1000.0) / (dist / 1000.0);\n        }\n        _fLapT0 = tEnd;\n        _fLapD0 = dEnd;\n        _fLapNo += 1;\n    }\n\n    private function fldLapPace() as Float {\n        var d = _fDist - _fLapD0;\n        if (d < 20.0) { return -1.0; }\n        return ((_fTimer - _fLapT0) / 1000.0) / (d / 1000.0);\n    }\n\n    private function fldAvgPace() as Float {\n        if (_fDist < 20.0) { return -1.0; }\n        return (_fTimer / 1000.0) / (_fDist / 1000.0);\n    }\n\n    private function fldPace(secPerKm as Float) as String {\n        if (secPerKm < 0.0 || secPerKm > 3599.0) { return \"--:--\"; }\n        var s = (secPerKm + 0.5).toNumber();\n        return (s / 60).format(\"%d\") + \":\" + (s % 60).format(\"%02d\");\n    }\n\n    private function fldTime(ms as Number) as String {\n        var s = ms / 1000;\n        var h = s / 3600;\n        var m = (s % 3600) / 60;\n        var sec = s % 60;\n        if (h > 0) { return h.format(\"%d\") + \":\" + m.format(\"%02d\") + \":\" + sec.format(\"%02d\"); }\n        return m.format(\"%02d\") + \":\" + sec.format(\"%02d\");\n    }\n\n    // 0 = below zone 1, 1..5 = zones\n    private function fldZone(hr) as Number {\n        if (hr == null || _fZones == null) { return 0; }\n        var z = 0;\n        for (var i = 0; i < 5; i++) {\n            if (hr >= _fZones[i]) { z = i + 1; }\n        }\n        return z;\n    }\n\n    private function fldAng(a as Number) as Number {\n        a = a % 360;\n        if (a < 0) { a += 360; }\n        return a;\n    }\n\n    private function fx(x as Float) as Float { return _fOx + x * _fK; }\n    private function fy(y as Float) as Float { return _fOy + y * _fK; }\n\n    // ---------- stroke text (8 x 12 glyph box, y down) ----------\n\n    private function fldWidth(s as String, u as Float) as Float {\n        var chars = s.toCharArray();\n        var tot = 0;\n        for (var i = 0; i < chars.size(); i++) {\n            var c = chars[i];\n            if (c == ' ') { tot += FieldGlyphs.SPACE; continue; }\n            var g = FieldGlyphs.DATA[c];\n            tot += ((g == null) ? 8 : g[0]) + FieldGlyphs.GAP;\n        }\n        return (tot - FieldGlyphs.GAP) * u;\n    }\n\n    private function fldPen(u as Float) as Number {\n        var p = (u * 1.5).toNumber();\n        return (p < 2) ? 2 : p;\n    }\n\n    // align 0 left / 1 centre / 2 right; y = top of the glyph box; halo = black outline (for text over the map)\n    private function fldText(dc as Dc, s as String, x as Float, y as Float, u as Float, color as Number, align as Number, halo as Boolean) as Void {\n        var chars = s.toCharArray();\n        var pen = fldPen(u);\n        var ox = x;\n        if (align == 1) { ox = x - fldWidth(s, u) / 2.0; }\n        else if (align == 2) { ox = x - fldWidth(s, u); }\n        for (var pass = halo ? 0 : 1; pass < 2; pass++) {\n            var p = (pass == 0) ? pen + 4 : pen;\n            dc.setColor((pass == 0) ? F_BLACK : color, Graphics.COLOR_TRANSPARENT);\n            dc.setPenWidth(p);\n            var round = (pass == 1 && pen >= 4);\n            var gx0 = ox;\n            for (var i = 0; i < chars.size(); i++) {\n                var c = chars[i];\n                if (c == ' ') { gx0 += FieldGlyphs.SPACE * u; continue; }\n                var g = FieldGlyphs.DATA[c];\n                if (g == null) { gx0 += (8 + FieldGlyphs.GAP) * u; continue; }\n                fldStrokes(dc, g, gx0, y, u, p, round);\n                gx0 += (g[0] + FieldGlyphs.GAP) * u;\n            }\n        }\n        dc.setPenWidth(1);\n    }\n\n    private function fldStrokes(dc as Dc, arr as Array, bx as Float, by as Float, u as Float, pen as Number, round as Boolean) as Void {\n        var n = arr.size();\n        var have = false;\n        var psx = 0.0;\n        var psy = 0.0;\n        var r = (pen + 1) / 2;\n        for (var i = 1; i + 1 < n; i += 2) {\n            var gx = arr[i];\n            if (gx == 99) { have = false; continue; }\n            var gy = arr[i + 1];\n            var sx = bx + gx * u;\n            var sy = by + gy * u;\n            if (have) {\n                dc.drawLine(psx, psy, sx, sy);\n                if (!round && psx == sx && psy == sy) { dc.fillCircle(sx, sy, r); }\n            }\n            if (round) { dc.fillCircle(sx, sy, r); }\n            psx = sx;\n            psy = sy;\n            have = true;\n        }\n    }\n\n    // ---------- heart-rate zone ring ----------\n\n    private function fldRing(dc as Dc, zone as Number) as Void {\n        var cx = fx(140.0).toNumber();\n        var cy = fy(140.0).toNumber();\n        var r = (133.0 * _fK).toNumber();\n        for (var i = 0; i < 5; i++) {\n            var on = (zone == i + 1);\n            var start = 210 + i * 61;\n            dc.setPenWidth(on ? (9.0 * _fK).toNumber() : (4.0 * _fK).toNumber());\n            dc.setColor(on ? F_ZBRIGHT[i] : F_ZDIM[i], Graphics.COLOR_TRANSPARENT);\n            dc.drawArc(cx, cy, r, Graphics.ARC_CLOCKWISE, fldAng(90 - start), fldAng(90 - (start + 56)));\n        }\n        dc.setPenWidth(1);\n    }\n\n    // ---------- route trail ----------\n\n    private function fldTrack(info as Activity.Info) as Void {\n        var loc = info.currentLocation;\n        if (loc == null) { return; }\n        var deg = loc.toDegrees();\n        var la = deg[0].toFloat();\n        var lo = deg[1].toFloat();\n        if (la == 0.0 && lo == 0.0) { return; }\n        _fHereLa = la;\n        _fHereLo = lo;\n        _fHave = true;\n        if (_fN > 0) {\n            var dy = (la - _fLat[_fN - 1]) * 111320.0;\n            var dx = (lo - _fLon[_fN - 1]) * 111320.0 * Math.cos(Math.toRadians(la));\n            if (dx * dx + dy * dy < _fStep * _fStep) { return; }\n        }\n        if (_fN >= 158) { fldThin(); }\n        _fLat[_fN] = la;\n        _fLon[_fN] = lo;\n        _fN += 1;\n    }\n\n    // keep every second point and double the spacing, so a long run still fits\n    private function fldThin() as Void {\n        var m = _fN / 2;\n        for (var i = 0; i < m; i++) {\n            _fLat[i] = _fLat[i * 2];\n            _fLon[i] = _fLon[i * 2];\n        }\n        _fN = m;\n        _fStep = _fStep * 2.0;\n    }\n\n    private function fldDrawMap(dc as Dc) as Void {\n        if (_fN < 1 || !_fHave) { return; }\n        var minLa = _fHereLa;\n        var maxLa = _fHereLa;\n        var minLo = _fHereLo;\n        var maxLo = _fHereLo;\n        for (var i = 0; i < _fN; i++) {\n            var a = _fLat[i];\n            var o = _fLon[i];\n            if (a < minLa) { minLa = a; }\n            if (a > maxLa) { maxLa = a; }\n            if (o < minLo) { minLo = o; }\n            if (o > maxLo) { maxLo = o; }\n        }\n        var midLa = (minLa + maxLa) / 2.0;\n        var midLo = (minLo + maxLo) / 2.0;\n        var cl = Math.cos(Math.toRadians(midLa));\n        // farthest point from the middle decides the zoom, so everything stays inside the circle\n        var far = 0.0000001;\n        for (var i = 0; i < _fN; i++) {\n            var ex = (_fLon[i] - midLo) * cl;\n            var ey = _fLat[i] - midLa;\n            var e = Math.sqrt(ex * ex + ey * ey);\n            if (e > far) { far = e; }\n        }\n        var ex2 = (_fHereLo - midLo) * cl;\n        var ey2 = _fHereLa - midLa;\n        var e2 = Math.sqrt(ex2 * ex2 + ey2 * ey2);\n        if (e2 > far) { far = e2; }\n        var sc = (108.0 * _fK) / far;\n        _fMLa = midLa;\n        _fMLo = midLo;\n        _fMCl = cl;\n        _fMSc = sc;\n        var cx = fx(140.0);\n        var cy = fy(140.0);\n        dc.setColor(F_TRAIL, Graphics.COLOR_TRANSPARENT);\n        dc.setPenWidth(3);\n        var px = 0.0;\n        var py = 0.0;\n        for (var i = 0; i < _fN; i++) {\n            var x = cx + (_fLon[i] - midLo) * cl * sc;\n            var y = cy - (_fLat[i] - midLa) * sc;\n            if (i > 0) { dc.drawLine(px, py, x, y); }\n            px = x;\n            py = y;\n        }\n        dc.drawLine(px, py, cx + (_fHereLo - midLo) * cl * sc, cy - (_fHereLa - midLa) * sc);\n        dc.setPenWidth(1);\n        // start (green)\n        dc.setColor(F_GREEN, Graphics.COLOR_TRANSPARENT);\n        dc.fillCircle(cx + (_fLon[0] - midLo) * cl * sc, cy - (_fLat[0] - midLa) * sc, 4);\n    }\n\n    // you (yellow): drawn last, on top of the numbers\n    private function fldDrawHere(dc as Dc) as Void {\n        if (!_fHave || _fN < 1) { return; }\n        var hx = fx(140.0) + (_fHereLo - _fMLo) * _fMCl * _fMSc;\n        var hy = fy(140.0) - (_fHereLa - _fMLa) * _fMSc;\n        dc.setColor(F_BLACK, Graphics.COLOR_TRANSPARENT);\n        dc.fillCircle(hx, hy, 7);\n        dc.setColor(F_YELLOW, Graphics.COLOR_TRANSPARENT);\n        dc.fillCircle(hx, hy, 5);\n    }\n\n    // ---------- the screen ----------\n\n    function fldDraw(dc as Dc) as Void {\n        var w = dc.getWidth();\n        var h = dc.getHeight();\n        _fK = ((w < h) ? w : h) / 280.0;\n        _fOx = w / 2.0 - 140.0 * _fK;\n        _fOy = h / 2.0 - 140.0 * _fK;\n        var halo = FLD_MAP;\n        var k = _fK;\n\n        var zone = fldZone(_fHr);\n        fldRing(dc, zone);\n        if (FLD_MAP) { fldDrawMap(dc); }\n\n        // timer, top centre (shrinks if it passes an hour)\n        var ts = fldTime(_fTimer);\n        var tu = 2.4 * k;\n        var tw = fldWidth(ts, tu);\n        if (tw > 130.0 * k) { tu = tu * 130.0 * k / tw; }\n        fldText(dc, ts, fx(140.0), fy(40.0), tu, F_WHITE, 1, halo);\n\n        // heart rate (zone colour) and distance\n        var zc = (zone >= 1) ? F_ZBRIGHT[zone - 1] : F_LGREY;\n        fldText(dc, (zone >= 1) ? \"HR Z\" + zone.format(\"%d\") : \"HR\", fx(84.0), fy(76.0), 1.0 * k, zc, 1, halo);\n        fldText(dc, (_fHr == null) ? \"--\" : _fHr.format(\"%d\"), fx(84.0), fy(90.0), 2.7 * k, zc, 1, halo);\n        fldText(dc, \"KM\", fx(196.0), fy(76.0), 1.0 * k, F_LGREY, 1, halo);\n        fldText(dc, (_fDist / 1000.0).format(\"%.2f\"), fx(196.0), fy(90.0), 1.8 * k, F_WHITE, 1, halo);\n\n        // current lap pace: the big one\n        var lapLabel = \"LAP \" + _fLapNo.format(\"%d\") + \"  \" + ((_fDist - _fLapD0) / 1000.0).format(\"%.2f\") + \" KM\";\n        fldText(dc, lapLabel, fx(140.0), fy(130.0), 1.0 * k, F_LGREY, 1, halo);\n        fldText(dc, fldPace(fldLapPace()), fx(140.0), fy(143.0), 3.5 * k, F_CYAN, 1, halo);\n\n        // average pace and last lap pace\n        fldText(dc, \"AVG\", fx(105.0), fy(196.0), 1.0 * k, F_LGREY, 1, halo);\n        fldText(dc, fldPace(fldAvgPace()), fx(105.0), fy(208.0), 1.7 * k, F_WHITE, 1, halo);\n        fldText(dc, \"LAST\", fx(175.0), fy(196.0), 1.0 * k, F_LGREY, 1, halo);\n        fldText(dc, fldPace(_fLastLap), fx(175.0), fy(208.0), 1.7 * k, F_WHITE, 1, halo);\n        if (FLD_MAP) { fldDrawHere(dc); }\n    }"
